import numpy as np, os, re
from scipy import ndimage
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
# test on 8conn with subgrid-search within comp bboxes, across ALL demo pairs:
for name in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    inp=np.array(G[name+' input']); v=int(inp[inp!=0][0]); out=np.array(G[name+' output'])
    lab,n=ndimage.label(inp==v, structure=np.ones((3,3)))
    ok=[]
    for k in range(1,n+1):
        ys,xs=np.where(lab==k)
        c=inp[ys.min():ys.max()+1,xs.min():xs.max()+1]
        h_,w_=c.shape
        for i in range(h_-out.shape[0]+1):
            for j in range(w_-out.shape[1]+1):
                if np.array_equal(c[i:i+out.shape[0],j:j+out.shape[1]],out):
                    ok.append((len(np.where(lab==k)),(int(ys.min()),int(xs.min())),i,j,c.shape,out.shape))
    print(name,'matches:',ok)
